import{_ as t,o,c as a,a2 as r}from"./chunks/framework.CyZTVJbV.js";const m=JSON.parse('{"title":"Frontend real-driver testing — 8 axis × 3 target = 24 cell grid + browser-shaped env-gate (SSOT)","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/frontend-real-driver-testing.md","filePath":"concepts/frontend-real-driver-testing.md"}'),d={name:"concepts/frontend-real-driver-testing.md"};function n(s,e,i,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="frontend-real-driver-testing-—-8-axis-×-3-target-24-cell-grid-browser-shaped-env-gate-ssot" tabindex="-1">Frontend real-driver testing — 8 axis × 3 target = 24 cell grid + browser-shaped env-gate (SSOT) <a class="header-anchor" href="#frontend-real-driver-testing-—-8-axis-×-3-target-24-cell-grid-browser-shaped-env-gate-ssot" aria-label="Permalink to &quot;Frontend real-driver testing — 8 axis × 3 target = 24 cell grid + browser-shaped env-gate (SSOT)&quot;">​</a></h1><p>kiwa&#39;s v1.16 component work covered the <strong>6 base axes</strong> (story registration / args resolution / play function / mount / a11y / visual regression) as unified mocks for Storybook 8 + Playwright Component Testing + Chromatic — the <code>docs/concepts/component-testing.md</code> doc is the SSOT for those 6 axes. v1.34 adds <strong>8 advanced axes on top of that base</strong> — the ones production frontend stacks hit once their mock-only Storybook suite is green but real React 19 + Next.js 15 behavior (RSC streaming with Suspense fallbacks, view transitions during navigation, form actions with useOptimistic + useFormStatus, revalidatePath + revalidateTag + redirect from Server Actions) starts showing up in Playwright regression reports. This concept doc is the SSOT for those 8 axes; the tutorials (67-69) and dogfood app new (v1.34-2/3/4) are the concrete implementations.</p><h2 id="the-8-axis-grid" tabindex="-1">The 8-axis grid <a class="header-anchor" href="#the-8-axis-grid" aria-label="Permalink to &quot;The 8-axis grid&quot;">​</a></h2><p>The 8 advanced axes are cover-oriented — each one names a real-world failure surface every non-trivial React 19 + Next.js 15 stack hits within the first month.</p><table tabindex="0"><thead><tr><th>Axis</th><th>Real-world failure it catches</th><th>v0.3 / v1.2 API</th></tr></thead><tbody><tr><td>RSC harness</td><td>&quot;Server Component streamed HTML but the Suspense fallback never got replaced by the resolved chunk&quot; (no boundary tracking, no chunk order assertion)</td><td><code>startRscHarness</code> / <code>beginRscRender</code> / <code>enterSuspenseBoundary</code> / <code>streamHtmlChunk</code> / <code>completeRscRender</code></td></tr><tr><td>Streaming SSR</td><td>&quot;Selective hydration finished 3 boundaries but the 4th stayed pending forever because the error boundary swallowed it&quot; (no per-boundary state machine, no error correlation)</td><td><code>startStreamingSsr</code> / <code>markSuspensePending</code> / <code>captureErrorBoundary</code> / <code>startProgressiveHydration</code> / <code>completeSelectiveHydration</code></td></tr><tr><td>View transitions</td><td>&quot;The document transition started but the element transition never finished because we forgot to await the animation promise&quot; (no per-element tracking, no assertion timing)</td><td><code>startViewTransitionSession</code> / <code>startElementTransition</code> / <code>finishElementTransition</code> / <code>startDocumentTransition</code> / <code>assertAnimation</code></td></tr><tr><td>Form action advanced</td><td>&quot;useOptimistic patched the UI but the resolved Server Action returned a different shape and the optimistic patch stuck&quot; (no patch ledger, no resolved-vs-optimistic diff)</td><td><code>startFormActionSession</code> / <code>markFormStatusPending</code> / <code>applyOptimisticUpdate</code> / <code>enableProgressiveEnhancement</code> / <code>resolveFormAction</code> / <code>rejectFormAction</code></td></tr><tr><td>Server action advanced</td><td>&quot;The Server Action revalidated the wrong path because the tag string was typoed&quot; (no path prefix guard, no tag-vs-path enforcement)</td><td><code>startServerActionAdvanced</code> / <code>submitFormAction</code> / <code>revalidateActionPath</code> / <code>revalidateActionTag</code> / <code>redirectAction</code></td></tr><tr><td>Partial prerendering</td><td>&quot;The static shell rendered but the dynamic hole never flushed because Suspense boundary was outside the shell&quot; (no shell-vs-hole boundary check, no streaming assertion)</td><td><code>startPartialPrerendering</code> / <code>renderStaticShell</code> / <code>openDynamicHole</code> / <code>flushStreamingBoundary</code> / <code>completePartialPrerendering</code></td></tr><tr><td>Interception routes</td><td>&quot;The modal opened via intercept.modal_opened but the current-segment matcher swallowed the wrong path prefix&quot; (no matcher unit test, no segment-level assertion)</td><td><code>startInterceptionRoutes</code> / <code>interceptCurrentSegment</code> / <code>interceptParentSegment</code> / <code>interceptRootCatchall</code> / <code>openInterceptedModal</code></td></tr><tr><td>Parallel routes advanced</td><td>&quot;The default slot rendered but the loading slot never showed because we forgot to add loading.tsx&quot; (no slot state machine, no loading-vs-default enforcement)</td><td><code>startParallelRoutesAdvanced</code> / <code>renderDefaultSlot</code> / <code>renderLoadingState</code> / <code>captureParallelError</code> / <code>navigateSlot</code></td></tr></tbody></table><p>Each axis has 3 shapes — a mock-only path (fast inner loop, ms scale), a real-driver path (<code>KIWA_MODE=real</code> + Playwright + Chromium browser session, seconds scale), and a fidelity assertion that the two produce the same output. Tutorial 67 covers the RSC + streaming SSR + view-transitions axes for the Next.js 15 App Router dogfood app, tutorial 68 covers form-action-advanced + server-action-advanced for the Server Action dogfood app, tutorial 69 covers all 4 component axes exercised through Storybook 8 + MDX + interaction test + coverage report.</p><h2 id="the-3-target-×-8-axis-24-cell-grid" tabindex="-1">The 3-target × 8-axis = 24 cell grid <a class="header-anchor" href="#the-3-target-×-8-axis-24-cell-grid" aria-label="Permalink to &quot;The 3-target × 8-axis = 24 cell grid&quot;">​</a></h2><p>Every target covers every axis. The mock shapes are target-neutral (the API surface is the same across Storybook 8 / Playwright CT / Chromatic for component axes, App Router / Pages Router / Edge Runtime for Next.js axes), the emitted event dialects are target-specific (<code>storybook.suspense.fallback</code> vs <code>pwct.locator.suspense.fallback</code> vs <code>chromatic.capture.suspense</code>), and the fidelity harness reports the coverage explicitly.</p><p><strong>Component 4 axis × 3 target grid (12 cells).</strong></p><table tabindex="0"><thead><tr><th>Target</th><th>1 RSC</th><th>2 SSR</th><th>3 View</th><th>4 Form</th></tr></thead><tbody><tr><td>Storybook 8</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr><tr><td>Playwright CT</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr><tr><td>Chromatic</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr></tbody></table><p><strong>Next.js 4 axis × 3 target grid (12 cells).</strong></p><table tabindex="0"><thead><tr><th>Target</th><th>1 Server Action</th><th>2 PPR</th><th>3 Intercept</th><th>4 Parallel</th></tr></thead><tbody><tr><td>App Router</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr><tr><td>Pages Router</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr><tr><td>Edge Runtime</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr></tbody></table><p>Unlike v1.31 streaming (where NATS has no Kafka wire protocol, so 6 of 24 cells are <code>not-applicable</code>), the v1.34 frontend grid is fully covered — every target implements every axis because the semantics are runtime-agnostic. That is what makes cross-target reuse (a story that runs under Storybook 8 + Playwright CT + Chromatic without change) even possible.</p><h3 id="why-the-frontend-grid-is-fully-covered-while-streaming-is-not" tabindex="-1">Why the frontend grid is fully covered while streaming is not <a class="header-anchor" href="#why-the-frontend-grid-is-fully-covered-while-streaming-is-not" aria-label="Permalink to &quot;Why the frontend grid is fully covered while streaming is not&quot;">​</a></h3><p>React 19 + Next.js 15 landed the same semantics (RSC streaming, Suspense boundary, view transitions, Server Actions with revalidatePath / revalidateTag / redirect) across App Router + Pages Router + Edge Runtime — the runtime surface converged at the framework level. Storybook 8 + Playwright CT + Chromatic each expose the same 4 component axes through different rendering pipelines but with the same neutral events. The v1.34 fidelity grid at 24/24 = 100 % implemented reflects that convergence at the framework surface.</p><h2 id="the-kiwa-mode-real-env-gate-contract" tabindex="-1">The <code>KIWA_MODE=real</code> env-gate contract <a class="header-anchor" href="#the-kiwa-mode-real-env-gate-contract" aria-label="Permalink to &quot;The `KIWA_MODE=real` env-gate contract&quot;">​</a></h2><p><code>resolveMode(target, env)</code> returns <code>{ mode: &#39;real&#39;, reason: &#39;kiwa-mode-real&#39; }</code> when both <code>env.KIWA_MODE === &#39;real&#39;</code> and the target&#39;s required env is present. <code>assertMode(target, &#39;real&#39;, env)</code> throws when the env is not configured — the dogfood apps use this at startup.</p><p>Per-target env mapping.</p><ul><li><strong>RSC streaming dogfood</strong> → <code>RSC_STREAMING_BROWSER_READY=1</code> (Playwright + Chromium browser session ready)</li><li><strong>Server Action dogfood</strong> → <code>SERVER_ACTION_BROWSER_READY=1</code> (Playwright + Chromium browser session ready)</li><li><strong>Storybook 8 MDX dogfood</strong> → <code>STORYBOOK_URL</code> + <code>STORYBOOK_MDX_READY=1</code> + <code>STORYBOOK_TEST_READY=1</code> (Storybook 8 server + MDX doc + interaction runner all ready)</li></ul><p>A test that respects the contract runs the mock path unconditionally and the real-driver path only when both <code>KIWA_MODE=real</code> and the required env are present. That means CI stays cheap by default (mock only, ms scale), the nightly Playwright job flips both envs (real browser + real Storybook server), and the fidelity harness ties the two together.</p><p>Absent env means silently fall back to mock mode with a target-specific <code>_ENV_MISSING</code> reason (<code>KIWA_RSC_STREAMING_ENV_MISSING</code> / <code>KIWA_SERVER_ACTION_ENV_MISSING</code> / <code>STORYBOOK_MDX_REAL_ENV_MISSING</code>). Absent <code>KIWA_MODE</code> means fall back with <code>reason: &#39;default-mock&#39;</code>. An invalid <code>KIWA_MODE</code> value (anything other than <code>real</code> or <code>mock</code>) reports <code>reason: &#39;invalid-mode&#39;</code> — the fallback is still mock so a typo does not break tests.</p><h2 id="the-dogfood-app-new-pattern" tabindex="-1">The dogfood app new pattern <a class="header-anchor" href="#the-dogfood-app-new-pattern" aria-label="Permalink to &quot;The dogfood app new pattern&quot;">​</a></h2><p>The 3 dogfood apps (v1.34-2/3/4) each expose a <code>pnpm test:real</code> command that flips <code>KIWA_MODE=real</code> and routes through the browser session.</p><ul><li><code>examples/dogfood-nextjs-rsc-streaming-app</code> new — Next.js 15.4 App Router + React 19.1 + RSC + Suspense + view transitions + form action advanced + Playwright e2e that walks the streaming flow (article render → catalog Suspense boundary → view transition → form action submit → optimistic patch → resolve).</li><li><code>examples/dogfood-nextjs-server-action-app</code> new — Next.js 15.4 + Server Actions + useFormStatus + useOptimistic + revalidatePath + revalidateTag + redirect + progressive enhancement + Playwright e2e that walks the form flow (subscribe → like optimistic → login redirect → all 3 surface revalidate).</li><li><code>examples/dogfood-storybook-8-mdx-app</code> new — Storybook 8 + MDX doc + interaction runner + coverage reporter + a11y checker + Playwright e2e that walks the story flow (12 primitive + 3 layout + 5 interaction focus story → MDX render → play interaction → a11y assert → coverage report).</li></ul><p>The pattern each new app follows.</p><ol><li>Keep the mock-only path (<code>pnpm test</code>) green — the fast inner loop stays sub-second.</li><li>Add a <code>pnpm test:e2e</code> command that spins Playwright + Chromium and walks the real browser flow.</li><li>Add a <code>pnpm test:real</code> command that requires the browser-ready env (<code>RSC_STREAMING_BROWSER_READY=1</code> / <code>SERVER_ACTION_BROWSER_READY=1</code> / <code>STORYBOOK_MDX_READY=1</code> + <code>STORYBOOK_TEST_READY=1</code>) and routes through the real Storybook + Playwright session.</li><li>Run the same fidelity-harness assertions against the real driver; failure means &quot;the mock diverged from real browser behavior&quot; — the mock gets the fix.</li><li>Emit a <code>quality-report/fidelity-latest.md</code> + <code>.json</code> that the v1.29 3-layer defensive structure (release-invariants + docs-e2e + release-smoke) picks up on merge.</li></ol><h2 id="the-not-implemented-failure-mode" tabindex="-1">The <code>not-implemented</code> failure mode <a class="header-anchor" href="#the-not-implemented-failure-mode" aria-label="Permalink to &quot;The `not-implemented` failure mode&quot;">​</a></h2><p>If the fidelity harness has a <code>planned</code> cell, the corresponding tutorial + dogfood + snippet-validation-test trio does not exist yet. The 24-cell grid at v1.34 has 0 <code>planned</code> cells — every intended cell is <code>implemented</code>. When a future milestone adds a 9th axis (e.g., <code>react-19-actions-hook</code> or <code>next-15-typed-routes</code>), it will start as <code>planned</code> for all 3 targets, then transition to <code>implemented</code> for the ones that cover it as the milestone lands its tutorial + dogfood + snippet test.</p><h2 id="how-this-ties-into-the-13-axis-release-gate" tabindex="-1">How this ties into the 13-axis release gate <a class="header-anchor" href="#how-this-ties-into-the-13-axis-release-gate" aria-label="Permalink to &quot;How this ties into the 13-axis release gate&quot;">​</a></h2><p>v1.34 does not add a 14th release-gate axis. The 8 advanced frontend axes gate the component + nextjs package&#39;s own tests (via <code>pnpm --filter @kiwa/component test</code> and <code>pnpm --filter @kiwa/nextjs test</code>) but do not surface as a per-package <code>@kiwa/quality-metrics</code> axis. The reasoning — the fidelity harness is target-shape-specific, and a package that does not use Storybook 8 / Playwright CT / Chromatic or App Router / Pages Router / Edge Runtime has nothing to assert on. When a future milestone adds a <code>frontend.fidelity</code> axis that describes &quot;which frontend targets this package&#39;s tests hit,&quot; it will slot into the 13-axis release gate as the 14th; v1.34 keeps the axis count at 13.</p><h2 id="ssot-boundaries" tabindex="-1">SSOT boundaries <a class="header-anchor" href="#ssot-boundaries" aria-label="Permalink to &quot;SSOT boundaries&quot;">​</a></h2><ul><li>The 6 base component axes (story registration / args / play / mount / a11y / visual regression) live in <code>docs/concepts/component-testing.md</code>. v1.34 does not modify that doc.</li><li>The 8 advanced axes (4 component + 4 nextjs) live in this doc. Tutorials 67-69 and the migration guide (v1.33 → v1.34) link back here for the axis SSOT.</li><li>The 3-target × 8-axis grid is the harness&#39;s data structure. The <code>collectFidelityCoverage()</code> implementations in <code>packages/component/src/semantics/fidelity.ts</code> + <code>packages/nextjs/src/semantics/fidelity.ts</code> are the code SSOT — this doc&#39;s grid tables are derived from that code.</li><li>The <code>KIWA_MODE=real</code> env-gate contract is shared with the v1.22 real-driver testing tutorial (auth adapters + Keycloak), the v1.31 streaming real-driver concept doc, the v1.32 database real-driver concept doc, and the v1.33 payment real-driver concept doc. All five use the same pattern; the frontend axes just add browser-ready envs (<code>RSC_STREAMING_BROWSER_READY</code> / <code>SERVER_ACTION_BROWSER_READY</code> / <code>STORYBOOK_MDX_READY</code> / <code>STORYBOOK_TEST_READY</code>) instead of provider <code>_KEY</code> envs.</li></ul>',32)])])}const g=t(d,[["render",n]]);export{m as __pageData,g as default};
